<section class="panel"><div class="panel-head"><div><h2>Webhook Deliveryها</h2><p>Retryها در درخواست‌های بعدی و با بودجه محدود اجرا می‌شوند.</p></div></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>پرداخت</th><th>وضعیت</th><th>تلاش</th><th>HTTP</th><th>مدت</th><th>Retry بعدی</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="empty">Delivery ثبت نشده است.</div></td></tr><?php else:foreach($rows as$row):?><tr><td><?= \CardPay\Core\View::e($row['event_type']) ?><small><code><?= \CardPay\Core\View::e($row['event_id']) ?></code></small></td><td><?= \CardPay\Core\View::e($row['public_id']) ?></td><td><span class="badge <?= $row['status']==='delivered'?'success':($row['status']==='pending'?'warning':'danger') ?>"><?= \CardPay\Core\View::e($row['status']) ?></span></td><td><?= (int)$row['attempt'] ?></td><td><?= \CardPay\Core\View::e($row['response_status']??'—') ?></td><td><?= $row['duration_ms']?(int)$row['duration_ms'].' ms':'—' ?></td><td><?= \CardPay\Core\View::e(\CardPay\Core\View::localDate($row['next_attempt_at']??null,(string)($settings['timezone']??'Asia/Tehran'))) ?></td><td><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/webhooks/'.$row['id'])) ?>">جزئیات</a></td></tr><?php endforeach;endif;?></tbody></table></div></section>
